package dev.leconnn.ioskeyboard.emoji

import android.content.Context
import android.graphics.Paint

/** Emoji from assets/emoji.tsv (generated by tools/emoji/gen_emoji.py), in iOS category order. */
class EmojiData(val sections: List<Section>) {

    class Emoji(val base: String, val name: String, val tones: List<String>)
    class Section(val title: String, val icon: String, val items: List<Emoji>)

    private val byBase = sections.flatMap { it.items }.associateBy { it.base }

    fun find(emoji: String): Emoji? = byBase[emoji]

    companion object {
        /** iOS order and section titles; the icon is the emoji shown in the bottom bar. */
        private val CATEGORIES = listOf(
            "Smileys & People" to "😀", "Animals & Nature" to "🐻", "Food & Drink" to "🍔",
            "Activity" to "⚽", "Travel & Places" to "🚗", "Objects" to "💡",
            "Symbols" to "🔣", "Flags" to "🏳️",
        )
        const val RECENTS_TITLE = "Frequently Used"
        const val RECENTS_ICON = "🕘"

        /** Reads the asset and drops emoji the device font can't draw. Call off the main thread. */
        fun load(context: Context): EmojiData {
            val paint = Paint()
            val byCategory = LinkedHashMap<String, MutableList<Emoji>>()
            context.assets.open("emoji.tsv").bufferedReader(Charsets.UTF_8).useLines { lines ->
                for (line in lines) {
                    if (line.startsWith("#")) continue
                    val f = line.split('\t')
                    if (f.size < 3 || !paint.hasGlyph(f[1])) continue
                    val tones = f.getOrNull(3).orEmpty().split(' ').filter { it.isNotEmpty() && paint.hasGlyph(it) }
                    byCategory.getOrPut(f[0]) { mutableListOf() }.add(Emoji(f[1], f[2], tones))
                }
            }
            return EmojiData(CATEGORIES.mapNotNull { (title, icon) ->
                byCategory[title]?.let { Section(title, icon, it) }
            })
        }
    }
}
